 allocate(key){if(this.p.ap<=0||!Object.hasOwn(this.p.attrs,key))return false;let old=stats(this.p);this.p.ap--;this.p.attrs[key]++;let s=stats(this.p);this.p.hp=Math.min(this.p.hp,s.hp);this.p.mp=Math.min(this.p.mp,s.mp);this.saveEvent();return true;}
 activeSkills(){return this.p.activeSkills.filter(k=>this.p.skills[k]>0&&!SKILLS[k]?.passive);}
 learnedSkills(){return Object.keys(this.p.skills).filter(k=>SKILLS[k]&&!SKILLS[k].passive&&this.p.skills[k]>0);}
 activateSkill(k,slot=null){const p=this.p;if(!this.learnedSkills().includes(k))return false;if(p.activeSkills.includes(k))return true;if(slot!==null&&(!Number.isInteger(slot)||slot<0||slot>=ACTIVE_LIMIT))return false;if(p.activeSkills.length>=ACTIVE_LIMIT&&slot===null){this.say('先选择要替换的激活位。');return false;}if(slot===null||slot>=p.activeSkills.length)p.activeSkills.push(k);else p.activeSkills[slot]=k;cleanBindings(p,SKILLS);this.saveEvent();return true;}
