 sell(id){const i=this.p.bag.find(i=>i.id===id);if(!this.canSell(i))return false;if(!['hall','town','guestroom','workshop','post','inn'].includes(this.map)||this.enemies.some(e=>!e.dead)){this.say('先回安全的街区或会馆整理战利品。');return false;}this.p.bag=this.p.bag.filter(v=>v.id!==id);const price=GEAR_SELL_PRICE[i.rarity]||6;this.p.gold+=price;this.say('卖出 '+i.name+' · '+price+' 金');this.saveEvent();return true;}
 equip(id,target){const p=this.p,item=p.bag.find(i=>i.id===id),plan=equipmentPlan(p,item,target||item?.slot);if(!plan){this.say(item?.minLevel>p.level?'等级还不够。':'这件装备无法放在这个位置。');return false;}if(p.bag.length-1+plan.removed.length>60){this.say('换装需要空出行囊位置。');return false;}p.bag=p.bag.filter(i=>i.id!==id);p.bag.push(...plan.removed);p.gear=plan.gear;const st=stats(p);p.hp=clamp(p.hp,0,st.hp);p.mp=clamp(p.mp,0,st.mp);this.saveEvent();return true;}
 unequip(slot){const i=this.p.gear[slot];if(!EQUIPMENT_SLOTS.includes(slot)||!i)return false;if(this.p.bag.length>=60){this.say('行囊满了，先整理一格再卸下。');return false;}this.p.bag.push({...i,slot:slot==='offhand'?'weapon':i.slot});this.p.gear[slot]=null;this.p.hp=clamp(this.p.hp,0,stats(this.p).hp);this.p.mp=clamp(this.p.mp,0,stats(this.p).mp);this.saveEvent();return true;}
