 nearest(range=Infinity){return this.enemies.filter(e=>!e.dead&&dist(e,this.p)<range).sort((a,b)=>dist(a,this.p)-dist(b,this.p))[0];}
 aim(includeProps=false){let t=this.enemies.find(e=>e.id===this.target&&!e.dead)||(includeProps?this.props.find(o=>o.id===this.target&&!o.action&&!o.broken):null);if(!t){const candidates=[...this.enemies.filter(e=>!e.dead&&dist(e,this.p)<CB.aimRange),...(includeProps?this.props.filter(o=>!o.action&&!o.broken&&dist(o,this.p)<CLASSES[this.p.cls].reach+25):[])];t=candidates.sort((a,b)=>dist(a,this.p)-dist(b,this.p))[0];}if(t)this.p.angle=Math.atan2(t.y-this.p.y,t.x-this.p.x);return t;}
 damage(e,n,kind='hit'){if(e.dead||!Number.isFinite(n)||n<=0)return;let p=this.p,s=stats(p),crit=!['dot','enchant','proc'].includes(kind)&&this.rng()<s.crit;n=kind==='enchant'?Math.round(n):Math.round(n*(crit?1.5:1)*(p.resonance>0?1.4:1)*playerDamageMultiplierV9(this,e,kind)*(e.fractureTime>0?e.fractureMultiplier||1:1));if(n<=0)return;registerDamageThreatV9(this,e,n,kind);e.hp-=n;if(['hit','skill','ch3skill'].includes(kind))p.emotion=clamp(p.emotion+(s.affixes.has('echo')?3:2),0,100);this.text((crit?'暴击 ':'')+n,e.x,e.y-65,kind==='dot'?'#da9cb9':crit?'#ffe08f':'#fff6de');if(!['dot','enchant','proc'].includes(kind)){if(kind==='skill'||kind==='ch3skill'){let a=Math.atan2(e.y-p.y,e.x-p.x);this.moveActor(e,e.x+Math.cos(a)*3,e.y+Math.sin(a)*3,false);}e.alertUntil=this.time+3;this.effect('sparks',e.x,e.y-25,24,CLASSES[p.cls].color,.22);this.hitstop=.035;this.shake=crit?3:1;p.combo++;p.comboLife=2.5;if(s.affixes.has('blood')&&!(p.cls==='saint'&&kind==='hit')){e.bleed=Math.min(4,e.bleed+1);e.bleedTime=CB.bleedDuration;}if(s.affixes.has('fire'))e.burn=3;this.emit('sfx',{name:'hit'});}if(['skill','ch3skill'].includes(kind)&&s.affixes.has('storm')&&!(p.cd.storm>0)){p.cd.storm=8;this.effect('lightning',e.x,e.y,115,'#b8d8eb',.35);for(const other of this.enemies.filter(o=>!o.dead&&dist(o,e)<115&&this.clearLine(e,o,false)))this.damage(other,s.atk*.9,'proc');}if(e.hp>0&&kind!=='proc')enchantProc(this,e,kind,basePower(p,CLASSES[p.cls]),t=>playerDamageMultiplierV9(this,t,'proc'));if(e.dead){this.saveEvent();return;}if(e.hp<=0){e.dead=true;e.aiState='DEAD';e.wind=0;e.telegraph=null;e.action=null;e.respawn=this.time+65;this.effect('fall',e.x,e.y-20,45,'#aaa7a0',.6);if(e.type==='rat'&&this.map==='warehouse')this.flags.rats=Math.min(6,this.flags.rats+1);if(this.handleHellDeath?.(e)){this.saveEvent();return;}this.gainXP(e.elite?65:e.type==='captain'?130:e.type==='wolf'?22:e.type==='guard'?20:12);p.gold+=e.elite?12:e.type==='captain'?35:2+Math.floor(this.rng()*3);if(kind!=='enchant'&&s.affixes.has('mercy'))this.heal(5);if(secretEnemyKilled(this,e)){this.saveEvent();return;}if(chapterEnemyKilled(this,e)){this.saveEvent();return;}if(e.type==='captain'){this.flags.captainDefeated=true;this.chapter=4;this.dropCombatLoot(e);this.say('追缉官倒地。东侧闸门已经打开。');}else if(e.id==='echo-warden'){if(!this.flags.echoWardenDefeated){this.flags.echoWardenDefeated=true;this.flags.echoCoreFound=true;this.addItem('echoCore');this.say('兽窝后找到一根完好的机芯。洛缇也许知道它的用处。');}}else this.dropCombatLoot(e);this.saveEvent();}}
 obtainGear(item){item=normalizeGear(item,this.p.cls);const unique=item.id.startsWith('ch3-')||item.id.startsWith('quest-')||!!item.uniqueEffect||item.name==='修钟人的银环';if(unique&&[...this.p.bag,...Object.values(this.p.gear),...this.pendingRewards].some(i=>i?.id===item.id))return false;if(this.p.bag.length>=60){if(unique){this.pendingRewards.push(item);this.say(item.name+'已妥善收起，腾出行囊后可在行囊领取。');}else{this.p.gold+=10;this.say('行囊已满，普通战利品折为 10 金。');}this.saveEvent();return unique;}this.p.bag.push(item);this.say('获得 '+item.name+' · 尚未装备');this.saveEvent();return true;}
